-- Faro instance schema v1 (ARCHITECTURE.md §4.4).
--
-- Portable between SQLite and Postgres (via sqlx's Any driver):
--   * integers are BIGINT; booleans are BIGINT 0/1;
--   * every timestamp is Unix milliseconds (UTC) in a BIGINT;
--   * binary values (keys, signatures) are base64url TEXT; ciphertext lives in
--     the blob store, never in the database;
--   * ids are TEXT generated by the server (no SERIAL/AUTOINCREMENT).
--
-- The instance only ever stores ciphertext and header metadata (§5.3).

CREATE TABLE instance (
    id              TEXT PRIMARY KEY,                 -- InstanceId (inst_…)
    singleton       BIGINT NOT NULL DEFAULT 1 UNIQUE CHECK (singleton = 1),
    name            TEXT NOT NULL,
    identity_pubkey TEXT NOT NULL,                    -- Ed25519, base64url
    settings_json   TEXT NOT NULL DEFAULT '{}',
    created_at      BIGINT NOT NULL
);

CREATE TABLE users (
    id            TEXT PRIMARY KEY,                   -- UserId (usr_…)
    email         TEXT NOT NULL UNIQUE,               -- normalised lowercase
    display_name  TEXT NOT NULL,
    is_admin      BIGINT NOT NULL DEFAULT 0 CHECK (is_admin IN (0, 1)),
    is_member     BIGINT NOT NULL DEFAULT 0 CHECK (is_member IN (0, 1)),
    is_ally       BIGINT NOT NULL DEFAULT 0 CHECK (is_ally IN (0, 1)),
    disabled      BIGINT NOT NULL DEFAULT 0 CHECK (disabled IN (0, 1)),
    created_at    BIGINT NOT NULL,
    last_login_at BIGINT
);

CREATE TABLE sessions (
    id_hash      TEXT PRIMARY KEY,                    -- keyed hash of the cookie value
    user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at   BIGINT NOT NULL,
    expires_at   BIGINT NOT NULL,
    last_seen_at BIGINT NOT NULL
);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE INDEX sessions_expires ON sessions(expires_at);

CREATE TABLE magic_links (
    token_hash TEXT PRIMARY KEY,
    email      TEXT NOT NULL,
    user_id    TEXT REFERENCES users(id) ON DELETE CASCADE,  -- NULL: open-registration signup
    created_at BIGINT NOT NULL,
    expires_at BIGINT NOT NULL,
    used_at    BIGINT
);
CREATE INDEX magic_links_expires ON magic_links(expires_at);

CREATE TABLE setup_tokens (
    token_hash TEXT PRIMARY KEY,
    created_at BIGINT NOT NULL,
    expires_at BIGINT NOT NULL,
    used_at    BIGINT
);

-- The member's own keys (§5.2). Private halves are passphrase/recovery
-- wrapped in the browser and opaque to the server.
CREATE TABLE member_keys (
    user_id          TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    sign_pubkey      TEXT NOT NULL UNIQUE,
    enc_pubkey       TEXT NOT NULL,
    enc_binding_json TEXT NOT NULL,                   -- Signed<MemberEncKeyBinding>
    wrapped_sign_key TEXT NOT NULL,                   -- opaque JSON
    wrapped_enc_key  TEXT NOT NULL,                   -- opaque JSON
    recovery_wrapped TEXT NOT NULL,                   -- opaque JSON
    created_at       BIGINT NOT NULL,
    updated_at       BIGINT NOT NULL
);

CREATE TABLE devices (
    id                 TEXT PRIMARY KEY,              -- DeviceId (dev_…)
    owner_user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    platform           TEXT NOT NULL,
    name               TEXT NOT NULL,
    client_version     TEXT NOT NULL,
    sign_pubkey        TEXT NOT NULL UNIQUE,
    token_hash         TEXT NOT NULL UNIQUE,
    status             TEXT NOT NULL
        CHECK (status IN ('pending_endorsement', 'active', 'removed')),
    member_sig         TEXT,                          -- Signed<DeviceEndorsement> JSON
    enrolled_at        BIGINT NOT NULL,
    endorsed_at        BIGINT,
    removed_at         BIGINT,
    -- Liveness (from heartbeats).
    last_seen_at       BIGINT,
    last_state         TEXT,
    last_boot_id       TEXT,
    reported_last_seq  BIGINT,
    reported_last_hash TEXT,
    -- Chain head as verified by the instance (from stored events).
    last_seq           BIGINT,
    last_hash          TEXT                           -- chain_hash of the head event, b3:hex
);
CREATE INDEX devices_owner ON devices(owner_user_id);

CREATE TABLE enroll_codes (
    code_hash  TEXT PRIMARY KEY,
    member_id  TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at BIGINT NOT NULL,
    expires_at BIGINT NOT NULL,
    used_at    BIGINT,
    device_id  TEXT REFERENCES devices(id) ON DELETE SET NULL
);
CREATE INDEX enroll_codes_member ON enroll_codes(member_id);

-- Member <-> ally relationships (populated by stage B invites).
CREATE TABLE ally_links (
    id               TEXT PRIMARY KEY,
    member_id        TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    ally_id          TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    state            TEXT NOT NULL CHECK (state IN ('pending', 'active', 'removed')),
    endorsement_json TEXT,                            -- Signed<AllyEndorsement>, set on approval
    created_at       BIGINT NOT NULL,
    activated_at     BIGINT,
    removed_at       BIGINT
);
CREATE INDEX ally_links_member ON ally_links(member_id, state);
CREATE INDEX ally_links_ally ON ally_links(ally_id, state);

CREATE TABLE ally_keys (
    id              TEXT PRIMARY KEY,
    user_id         TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    enc_pubkey      TEXT NOT NULL,
    key_id          TEXT NOT NULL,
    wrapped_privkey TEXT NOT NULL,                    -- opaque JSON (WrappedSecret)
    created_at      BIGINT NOT NULL,
    revoked_at      BIGINT
);
CREATE INDEX ally_keys_user ON ally_keys(user_id);

CREATE TABLE invites (
    token_hash TEXT PRIMARY KEY,
    kind       TEXT NOT NULL CHECK (kind IN ('member', 'ally')),
    inviter_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    email      TEXT,
    created_at BIGINT NOT NULL,
    expires_at BIGINT NOT NULL,
    used_at    BIGINT,
    used_by    TEXT REFERENCES users(id) ON DELETE SET NULL
);

-- Index of ciphertext blobs (content in the blob store).
CREATE TABLE blobs (
    id              TEXT PRIMARY KEY,                 -- 32 lowercase hex
    kind            TEXT NOT NULL CHECK (kind IN ('event_body', 'report')),
    owner_member_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    size            BIGINT NOT NULL,
    created_at      BIGINT NOT NULL
);
CREATE INDEX blobs_created ON blobs(created_at);

CREATE TABLE events (
    device_id         TEXT NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
    seq               BIGINT NOT NULL,
    member_id         TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    ts_ms             BIGINT NOT NULL,
    kind              TEXT NOT NULL,
    urgency           TEXT NOT NULL,                  -- as signed by the device
    effective_urgency TEXT NOT NULL,                  -- max(urgency, kind floor)
    header_json       TEXT NOT NULL,                  -- the signed header, verbatim
    header_hash       TEXT NOT NULL,                  -- chain_hash, b3:hex
    sig               TEXT NOT NULL,                  -- base64url
    blob_id           TEXT REFERENCES blobs(id) ON DELETE SET NULL,
    received_at       BIGINT NOT NULL,
    PRIMARY KEY (device_id, seq)
);
CREATE INDEX events_member_ts ON events(member_id, ts_ms);
CREATE INDEX events_received ON events(received_at);

CREATE TABLE event_recipients (
    device_id    TEXT NOT NULL,
    seq          BIGINT NOT NULL,
    recipient_id TEXT NOT NULL,                       -- device-declared; not trusted for access
    key_id       TEXT NOT NULL,
    PRIMARY KEY (device_id, seq, recipient_id, key_id),
    FOREIGN KEY (device_id, seq) REFERENCES events(device_id, seq) ON DELETE CASCADE
);
CREATE INDEX event_recipients_recipient ON event_recipients(recipient_id);

CREATE TABLE reports (
    id              TEXT PRIMARY KEY,
    member_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    device_id       TEXT NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
    period_start_ms BIGINT NOT NULL,
    period_end_ms   BIGINT NOT NULL,
    first_seq       BIGINT,
    last_seq        BIGINT,
    header_json     TEXT NOT NULL,
    header_hash     TEXT NOT NULL,                    -- BLAKE3 of signing bytes, b3:hex
    sig             TEXT NOT NULL,
    blob_id         TEXT REFERENCES blobs(id) ON DELETE SET NULL,
    received_at     BIGINT NOT NULL,
    UNIQUE (device_id, header_hash)
);
CREATE INDEX reports_member ON reports(member_id, period_end_ms);

CREATE TABLE report_recipients (
    report_id    TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE,
    recipient_id TEXT NOT NULL,
    key_id       TEXT NOT NULL,
    PRIMARY KEY (report_id, recipient_id, key_id)
);
CREATE INDEX report_recipients_recipient ON report_recipients(recipient_id);

-- Things allies may need to be told about. source = 'device' rows mirror an
-- uploaded event (kind = EventKind); source = 'server' rows are raised by the
-- instance itself (kind = ServerAlertKind). Consumed by the stage-B notifier.
CREATE TABLE alerts (
    id            TEXT PRIMARY KEY,
    member_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    device_id     TEXT REFERENCES devices(id) ON DELETE CASCADE,
    source        TEXT NOT NULL CHECK (source IN ('device', 'server')),
    kind          TEXT NOT NULL,
    urgency       TEXT NOT NULL CHECK (urgency IN ('none', 'normal', 'urgent')),
    event_seq     BIGINT,
    detail        TEXT,                               -- short machine code, never content
    dedupe_key    TEXT UNIQUE,                        -- suppresses repeats from retries
    created_at    BIGINT NOT NULL,
    dispatched_at BIGINT                              -- set once fanned out to notifications
);
CREATE INDEX alerts_member ON alerts(member_id, created_at);
CREATE INDEX alerts_undispatched ON alerts(dispatched_at, created_at);

CREATE TABLE notifications (
    id           TEXT PRIMARY KEY,
    alert_id     TEXT REFERENCES alerts(id) ON DELETE CASCADE,
    report_id    TEXT REFERENCES reports(id) ON DELETE CASCADE,
    recipient_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    channel      TEXT NOT NULL CHECK (channel IN ('email', 'web_push')),
    urgency      TEXT NOT NULL CHECK (urgency IN ('none', 'normal', 'urgent')),
    status       TEXT NOT NULL CHECK (status IN ('pending', 'sent', 'failed', 'suppressed')),
    attempts     BIGINT NOT NULL DEFAULT 0,
    last_error   TEXT,
    created_at   BIGINT NOT NULL,
    sent_at      BIGINT
);
CREATE INDEX notifications_status ON notifications(status, created_at);

CREATE TABLE notification_prefs (
    user_id         TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    member_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    urgency         TEXT NOT NULL CHECK (urgency IN ('none', 'normal', 'urgent')),
    channel         TEXT NOT NULL CHECK (channel IN ('email', 'web_push')),
    mode            TEXT NOT NULL CHECK (mode IN ('immediate', 'digest', 'off')),
    quiet_start_min BIGINT,                           -- minutes after local midnight
    quiet_end_min   BIGINT,
    timezone        TEXT,                             -- IANA name
    PRIMARY KEY (user_id, member_id, urgency, channel)
);

-- When this instance was up, so the liveness monitor never blames a device
-- for silence that overlaps the instance's own downtime (§3.7).
CREATE TABLE instance_uptime (
    id            TEXT PRIMARY KEY,
    started_at    BIGINT NOT NULL,
    last_alive_at BIGINT NOT NULL,
    stopped_at    BIGINT
);
CREATE INDEX instance_uptime_started ON instance_uptime(started_at);
